(function(){var i=(location.pathname.match(/^\/app\/join\/([A-Za-z0-9]+)/)||[])[1]||"",e=document.getElementById("join-btn"),t=document.getElementById("login-error");sbBoot().then(function(n){if(!n.ok){t.textContent=errMsg(n.code,n.params),t.classList.add("show");return}var o=n.data.invite;if(document.getElementById("join-name").textContent=o.name,o.already){location.replace("/app/g/"+o.group_id);return}e.disabled=!1,e.addEventListener("click",function(){setBusy(e,!0),api("invite/join",{body:{code:i}}).then(function(a){if(!a.ok){setBusy(e,!1),t.textContent=errMsg(a.code,a.params),t.classList.add("show");return}location.href="/app/g/"+a.data.group_id})})})})();
